import javax.crypto.Cipher;
import javax.crypto.spec.IvParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.util.Base64;
import java.security.SecureRandom;
import com.sun.net.httpserver.HttpServer;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpExchange;
import java.io.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Arrays;

public class SecureVaultServer {
    private static final byte[] MASTER_KEY = new byte[]{0x2b,0x7e,0x15,0x16,0x28,(byte)0xae,(byte)0xd2,(byte)0xa6,
                                                        (byte)0xab,(byte)0xf7,0x15,(byte)0x88,0x09,(byte)0xcf,0x4f,0x3c};
    private static final ConcurrentHashMap<String, byte[]> vault = new ConcurrentHashMap<>();
    private static final SecureRandom secureRandom = new SecureRandom();

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8443), 0);
        server.createContext("/api/vault/store", new StoreHandler());
        server.createContext("/api/vault/retrieve", new RetrieveHandler());
        server.setExecutor(null);
        server.start();
    }

    static class StoreHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }
            try {
                String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
                String[] parts = body.split("\\|");
                if (parts.length != 2) {
                    sendResponse(exchange, 400, "{\"error\":\"Invalid format\"}");
                    return;
                }
                String key = parts[0].trim();
                String value = parts[1].trim();
                byte[] encrypted = encryptValue(value.getBytes(StandardCharsets.UTF_8));
                vault.put(key, encrypted);
                sendResponse(exchange, 200, "{\"status\":\"stored\",\"id\":\"" + key + "\"}");
            } catch (Exception e) {
                sendResponse(exchange, 500, "{\"error\":\"Internal error\"}");
            }
        }
    }

    static class RetrieveHandler implements HttpHandler {
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equals(exchange.getRequestMethod())) {
                exchange.sendResponseHeaders(405, -1);
                return;
            }
            try {
                String body = new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
                String[] parts = body.split("\\|");
                String key = parts[0].trim();
                byte[] stored = vault.get(key);
                if (stored == null) {
                    sendResponse(exchange, 404, "{\"error\":\"Not found\"}");
                    return;
                }
                if (parts.length == 2) {
                    byte[] clientCiphertext = Base64.getDecoder().decode(parts[1].trim());
                    byte[] result = decryptAndVerify(clientCiphertext);
                    if (result != null) {
                        sendResponse(exchange, 200, "{\"data\":\"" + Base64.getEncoder().encodeToString(result) + "\"}");
                    } else {
                        sendResponse(exchange, 200, "{\"data\":\"" + Base64.getEncoder().encodeToString(decryptValue(stored)) + "\"}");
                    }
                } else {
                    byte[] decrypted = decryptValue(stored);
                    sendResponse(exchange, 200, "{\"data\":\"" + Base64.getEncoder().encodeToString(decrypted) + "\"}");
                }
            } catch (javax.crypto.BadPaddingException e) {
                sendResponse(exchange, 400, "{\"error\":\"Decryption failed: padding invalid\"}");
            } catch (Exception e) {
                sendResponse(exchange, 500, "{\"error\":\"Processing error\"}");
            }
        }
    }

    private static byte[] encryptValue(byte[] plaintext) throws Exception {
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        byte[] iv = new byte[16];
        secureRandom.nextBytes(iv);
        cipher.init(Cipher.ENCRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), new IvParameterSpec(iv));
        byte[] ciphertext = cipher.doFinal(plaintext);
        byte[] result = new byte[iv.length + ciphertext.length];
        System.arraycopy(iv, 0, result, 0, iv.length);
        System.arraycopy(ciphertext, 0, result, iv.length, ciphertext.length);
        return result;
    }

    private static byte[] decryptValue(byte[] data) throws Exception {
        byte[] iv = Arrays.copyOfRange(data, 0, 16);
        byte[] ciphertext = Arrays.copyOfRange(data, 16, data.length);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), new IvParameterSpec(iv));
        return cipher.doFinal(ciphertext);
    }

    private static byte[] decryptAndVerify(byte[] data) throws Exception {
        if (data.length < 32 || data.length % 16 != 0) {
            return null;
        }
        byte[] iv = Arrays.copyOfRange(data, 0, 16);
        byte[] ciphertext = Arrays.copyOfRange(data, 16, data.length);
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, new SecretKeySpec(MASTER_KEY, "AES"), new IvParameterSpec(iv));
        return cipher.doFinal(ciphertext);
    }

    private static void sendResponse(HttpExchange exchange, int code, String body) throws IOException {
        exchange.getResponseHeaders().set("Content-Type", "application/json");
        byte[] responseBytes = body.getBytes(StandardCharsets.UTF_8);
        exchange.sendResponseHeaders(code, responseBytes.length);
        try (OutputStream os = exchange.getResponseBody()) {
            os.write(responseBytes);
        }
    }
}
